"""Find all duplicate elements in an array using O(1) extra space.

Uses index-negation marking: for each value *v* in the array, treat
``abs(v) - 1`` as an index and negate the element there.  If the target
element is already negative, *v* is a duplicate.

Requires every element to be a positive integer in ``[1, n]`` where
``n = len(nums)``.  The array is restored to its original state before
returning.
"""


def rate_limiter(nums: list[int]) -> list[int]:
    """Return every value that appears more than once in *nums*.

    Works in O(n) time and O(1) extra space (the output list excluded).

    Args:
        nums: Positive integers, each in ``[1, len(nums)]``.

    Returns:
        Deduplicated list of values that occur at least twice.
    """
    duplicates: list[int] = []

    for num in nums:
        idx = abs(num) - 1
        if nums[idx] < 0:
            duplicates.append(abs(num))
        else:
            nums[idx] = -nums[idx]

    # Restore the original array so callers aren't surprised.
    for i in range(len(nums)):
        nums[i] = abs(nums[i])

    return duplicates


# ---------------------------------------------------------------------------
# Tests
# ---------------------------------------------------------------------------

def test_no_duplicates():
    assert rate_limiter([1, 2, 3, 4, 5]) == []


def test_single_duplicate():
    assert sorted(rate_limiter([1, 2, 3, 2])) == [2]


def test_multiple_duplicates():
    assert sorted(rate_limiter([4, 3, 2, 7, 8, 2, 3, 1])) == [2, 3]


def test_all_same():
    assert sorted(rate_limiter([3, 3, 3, 3])) == [3]


def test_two_elements_duplicate():
    assert sorted(rate_limiter([1, 1])) == [1]


def test_two_elements_no_duplicate():
    assert rate_limiter([1, 2]) == []


def test_single_element():
    assert rate_limiter([1]) == []


def test_empty_array():
    assert rate_limiter([]) == []


def test_duplicates_at_ends():
    assert sorted(rate_limiter([2, 1, 2])) == [2]


def test_three_duplicates():
    assert sorted(rate_limiter([2, 2, 2, 2])) == [2]


def test_large_array_with_duplicates():
    nums = list(range(1, 1001)) + [500]
    assert sorted(rate_limiter(nums)) == [500]


def test_array_not_mutated():
    original = [4, 3, 2, 7, 8, 2, 3, 1]
    copy = original[:]
    rate_limiter(original)
    assert original == copy


def test_several_overlapping_duplicates():
    assert sorted(rate_limiter([1, 1, 2, 2, 3, 3])) == [1, 2, 3]


def test_duplicate_appears_three_times():
    assert sorted(rate_limiter([1, 1, 1, 2])) == [1]


def test_every_element_duplicated():
    assert sorted(rate_limiter([1, 2, 3, 1, 2, 3])) == [1, 2, 3]


if __name__ == "__main__":
    import pytest
    pytest.main([__file__, "-v"])

